const item = $input.first();

// The Webhook node authenticates the caller with its Header Auth credential, so by the time
// this runs the request is already known to come from the backend. Raw Body is still on, so
// read the bytes the backend sent rather than a re-serialised copy.
let raw;
if (item.binary && item.binary.data && item.binary.data.data) {
  raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
} else {
  raw = JSON.stringify(item.json.body);
}

const task = JSON.parse(raw);
if (task.schemaVersion !== '1') {
  throw new Error('Unsupported schemaVersion "' + task.schemaVersion + '".');
}
if (!task.taskId || !task.callbackUrl || !task.file || !task.file.downloadUrl) {
  throw new Error('The task is missing required fields.');
}

return [{ json: task }];

const task = $('Read Task').first().json;
const file = task.file;

const downloaded = $('Download File').first();
if (!downloaded.binary || !downloaded.binary.data) {
  throw new Error('The file could not be downloaded from the backend.');
}

const SCHEMAS = {
